import pandas as pd


def _is_null(v):
    try:
        return pd.isna(v)
    except (TypeError, ValueError):
        return v is None


def _safe_eq(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return True
    if a_null != b_null:
        return False
    return a == b


def run(inputs: dict) -> dict:
    dim = inputs["dim_product"].copy()
    stg = inputs["stg_product"].copy()

    output_rows = []

    dim_product_ids = set(dim["product_id"].unique()) if len(dim) else set()
    stg_product_ids = set(stg["product_id"].unique()) if len(stg) else set()
    all_product_ids = dim_product_ids | stg_product_ids

    for pid in all_product_ids:
        dim_rows = dim[dim["product_id"] == pid]
        current_rows = dim_rows[dim_rows["is_current"] == 1]
        history_rows = dim_rows[dim_rows["is_current"] != 1]

        # historical (already-closed) rows pass through unchanged
        for _, r in history_rows.iterrows():
            output_rows.append(r.to_dict())

        if len(current_rows) > 0:
            current = current_rows.iloc[0].to_dict()
        else:
            current = None

        stg_rows = stg[stg["product_id"] == pid].sort_values("update_date", kind="mergesort")

        for _, s in stg_rows.iterrows():
            if current is None:
                current = {
                    "product_id": pid,
                    "category": s["category"],
                    "price_band": s["price_band"],
                    "eff_start_date": s["update_date"],
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                }
            else:
                changed = (
                    not _safe_eq(current["category"], s["category"])
                    or not _safe_eq(current["price_band"], s["price_band"])
                )
                if changed:
                    expired = dict(current)
                    expired["eff_end_date"] = s["update_date"]
                    expired["is_current"] = 0
                    output_rows.append(expired)

                    current = {
                        "product_id": pid,
                        "category": s["category"],
                        "price_band": s["price_band"],
                        "eff_start_date": s["update_date"],
                        "eff_end_date": pd.NaT,
                        "is_current": 1,
                    }
                # else: no-op, current stays as-is

        if current is not None:
            output_rows.append(current)

    columns = [
        "product_id",
        "category",
        "price_band",
        "eff_start_date",
        "eff_end_date",
        "is_current",
    ]

    result = pd.DataFrame(output_rows, columns=columns)

    if len(result) > 0:
        result["product_id"] = result["product_id"].astype("int64")
        result["eff_start_date"] = pd.to_datetime(result["eff_start_date"]).astype("datetime64[us]")
        result["eff_end_date"] = pd.to_datetime(result["eff_end_date"]).astype("datetime64[s]")
        result["is_current"] = result["is_current"].astype("int64")
    else:
        result = pd.DataFrame({
            "product_id": pd.Series(dtype="int64"),
            "category": pd.Series(dtype="object"),
            "price_band": pd.Series(dtype="object"),
            "eff_start_date": pd.Series(dtype="datetime64[us]"),
            "eff_end_date": pd.Series(dtype="datetime64[s]"),
            "is_current": pd.Series(dtype="int64"),
        })

    return {"dim_product_out": result}
